app.get('/api/health', (req, res) => {
  res.status(200).json({ status: 'ok' });
});

export async function getBooks(filters = {}) {
  const response = await axios.get(API_URL, { params: filters });
  return response.data;
}

export async function getBookById(id) {
  const response = await axios.get(`${API_URL}/${id}`);
  return response.data;
}

export async function addBook(book) {
  const response = await axios.post(API_URL, book);
  return response.data;
}

export async function updateBook(id, updates) {
  const response = await axios.put(`${API_URL}/${id}`, updates);
  return response.data;
}

export async function deleteBook(id) {
  const response = await axios.delete(`${API_URL}/${id}`);
  return response.data;
}

export default function App() {
  return (
    <div>
      <h1>My Bookshelf</h1>
      <BookList />
    </div>
  );
}

export function formatRating(rating) {
  const num = Number(rating);
  if (Number.isNaN(num) || num < 0) {
    return 'Unrated';
  }
  const clamped = Math.min(num, 5);
  return `${'★'.repeat(Math.round(clamped))}${'☆'.repeat(5 - Math.round(clamped))}`;
}

export function sortBooksByTitle(books) {
  if (!Array.isArray(books)) return [];
  return [...books].sort((a, b) => a.title.localeCompare(b.title));
}

export function filterUnreadBooks(books) {
  if (!Array.isArray(books)) return [];
  return books.filter((book) => !book.isRead);
}

export default function BookList() {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    getBooks()
      .then((data) => setBooks(data))
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  async function handleDelete(id) {
    await deleteBook(id);
    setBooks((prev) => prev.filter((book) => book._id !== id));
  }

  if (loading) return <p>Loading books...</p>;
  if (error) return <p role="alert">Error: {error}</p>;

  return (
    <ul aria-label="book-list">
      {books.map((book) => (
        <li key={book._id}>
          <span>{book.title}</span> by <span>{book.author}</span>{' '}
          <span>{formatRating(book.rating)}</span>
          <button onClick={() => handleDelete(book._id)}>Remove</button>
        </li>
      ))}
    </ul>
  );
}

async function getBooks(req, res) {
  try {
    const filter = {};
    if (req.query.genre) {
      filter.genre = req.query.genre;
    }
    if (req.query.isRead !== undefined) {
      filter.isRead = req.query.isRead === 'true';
    }
    const books = await Book.find(filter).sort({ createdAt: -1 });
    res.status(200).json(books);
  } catch (err) {
    res.status(500).json({ message: 'Failed to fetch books', error: err.message });
  }
}

async function getBookById(req, res) {
  try {
    const book = await Book.findById(req.params.id);
    if (!book) {
      return res.status(404).json({ message: 'Book not found' });
    }
    res.status(200).json(book);
  } catch (err) {
    res.status(500).json({ message: 'Failed to fetch book', error: err.message });
  }
}

async function addBook(req, res) {
  const { valid, errors } = validateBook(req.body);
  if (!valid) {
    return res.status(400).json({ message: 'Validation failed', errors });
  }
  try {
    const book = await Book.create(req.body);
    res.status(201).json(book);
  } catch (err) {
    res.status(500).json({ message: 'Failed to create book', error: err.message });
  }
}

async function updateBook(req, res) {
  if (Object.keys(req.body).length === 0) {
    return res.status(400).json({ message: 'No update fields provided' });
  }
  try {
    const book = await Book.findByIdAndUpdate(req.params.id, req.body, {
      new: true,
      runValidators: true,
    });
    if (!book) {
      return res.status(404).json({ message: 'Book not found' });
    }
    res.status(200).json(book);
  } catch (err) {
    res.status(500).json({ message: 'Failed to update book', error: err.message });
  }
}

async function deleteBook(req, res) {
  try {
    const book = await Book.findByIdAndDelete(req.params.id);
    if (!book) {
      return res.status(404).json({ message: 'Book not found' });
    }
    res.status(200).json({ message: 'Book deleted', id: req.params.id });
  } catch (err) {
    res.status(500).json({ message: 'Failed to delete book', error: err.message });
  }
}

const bookSchema = new mongoose.Schema(
  {
    title: {
      type: String,
      required: true,
      trim: true,
    },
    author: {
      type: String,
      required: true,
      trim: true,
    },
    genre: {
      type: String,
      default: 'Uncategorized',
    },
    rating: {
      type: Number,
      min: 0,
      max: 5,
      default: 0,
    },
    isRead: {
      type: Boolean,
      default: false,
    },
  },

function validateBook(payload) {
  const errors = [];

  if (!payload || typeof payload !== 'object') {
    return { valid: false, errors: ['Payload must be an object'] };
  }

  if (!payload.title || typeof payload.title !== 'string' || !payload.title.trim()) {
    errors.push('Title is required');
  }

  if (!payload.author || typeof payload.author !== 'string' || !payload.author.trim()) {
    errors.push('Author is required');
  }

  if (payload.rating !== undefined) {
    const rating = Number(payload.rating);
    if (Number.isNaN(rating) || rating < 0 || rating > 5) {
      errors.push('Rating must be a number between 0 and 5');
    }
  }

  if (payload.genre !== undefined && typeof payload.genre !== 'string') {
    errors.push('Genre must be a string');
  }

  return { valid: errors.length === 0, errors };
}

